import{_ as i,c as n,o as t,a0 as a}from"./chunks/framework.oTSD2LDJ.js";const h=JSON.parse('{"title":"UniDeskPluginMgr","description":"","frontmatter":{"title":"UniDeskPluginMgr","editLink":true},"headers":[],"relativePath":"en/controls-reference/cpp-ext/UniDeskPluginMgr.md","filePath":"en/controls-reference/cpp-ext/UniDeskPluginMgr.md"}'),s={name:"en/controls-reference/cpp-ext/UniDeskPluginMgr.md"};function l(o,e,r,d,p,c){return t(),n("div",null,e[0]||(e[0]=[a('<h1 id="unideskpluginmgr-type" tabindex="-1">UniDeskPluginMgr Type <a class="header-anchor" href="#unideskpluginmgr-type" aria-label="Permalink to &quot;UniDeskPluginMgr Type&quot;">​</a></h1><p>Plugin manager that scans and loads all C++ DLL plugins at application startup, exposing the QML types registered by plugins to the system. It is the unified entry point for both official and third-party plugins.</p><table tabindex="0"><thead><tr><th>Item</th><th>Description</th></tr></thead><tbody><tr><td>Control Type</td><td>Global Singleton</td></tr><tr><td>Source File</td><td><code>UniDesk/CppExt/UniDeskPluginMgr.h</code> / <code>.cpp</code></td></tr><tr><td>Inherits</td><td>QQuickItem</td></tr><tr><td>QML Import</td><td><code>import UniDesk 1.0</code></td></tr></tbody></table><h2 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to &quot;Properties&quot;">​</a></h2><h3 id="property-qvariantlist-plugins-list" tabindex="-1"><code>property QVariantList plugins_list</code> <a class="header-anchor" href="#property-qvariantlist-plugins-list" aria-label="Permalink to &quot;`property QVariantList plugins_list`&quot;">​</a></h3><p>List of currently loaded plugins. Each entry is a QVariantMap containing plugin metadata (name, author, version, supported type names, etc.).</p><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to &quot;Methods&quot;">​</a></h2><h3 id="function-loadplugins" tabindex="-1"><code>function loadPlugins()</code> <a class="header-anchor" href="#function-loadplugins" aria-label="Permalink to &quot;`function loadPlugins()`&quot;">​</a></h3><p>Scans the plugin directory and loads all valid DLL plugins. Internally uses <code>QPluginLoader</code> to load each one, then calls the plugin&#39;s <code>registerQmlTypes(engine)</code> and <code>initialize()</code> methods on success.</p><h3 id="function-unloadplugins" tabindex="-1"><code>function unloadPlugins()</code> <a class="header-anchor" href="#function-unloadplugins" aria-label="Permalink to &quot;`function unloadPlugins()`&quot;">​</a></h3><p>Unloads all loaded plugins and releases the <code>QPluginLoader</code> instances.</p><h3 id="function-setengine-engine" tabindex="-1"><code>function setEngine(engine)</code> <a class="header-anchor" href="#function-setengine-engine" aria-label="Permalink to &quot;`function setEngine(engine)`&quot;">​</a></h3><p>Sets the <code>QQmlApplicationEngine</code> instance used by plugins to register QML types. Typically called once in <code>main.cpp</code>.</p><h3 id="function-getengine-→-qqmlapplicationengine" tabindex="-1"><code>function getEngine() → QQmlApplicationEngine*</code> <a class="header-anchor" href="#function-getengine-→-qqmlapplicationengine" aria-label="Permalink to &quot;`function getEngine() → QQmlApplicationEngine*`&quot;">​</a></h3><p>Returns the current <code>QQmlApplicationEngine</code> instance.</p><h3 id="function-getplugindir-comtypeid-→-qstring" tabindex="-1"><code>function getPluginDir(comTypeId) → QString</code> <a class="header-anchor" href="#function-getplugindir-comtypeid-→-qstring" aria-label="Permalink to &quot;`function getPluginDir(comTypeId) → QString`&quot;">​</a></h3><p>Returns the installation directory of the plugin identified by <code>comTypeId</code> (format <code>author.id.name</code>). Used by plugin components to locate their own resource files at runtime.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><div class="language-qml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">qml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> UniDesk</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1.0</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Component.onCompleted: {</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    UniDeskPluginMgr.loadPlugins()</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    console.log(&quot;Loaded plugins:&quot;, UniDeskPluginMgr.plugins_list.length)</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">for (var i = 0; i &lt; UniDeskPluginMgr.plugins_list.length; i++) {</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    var p = UniDeskPluginMgr.plugins_list[i]</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    console.log(p.name, &quot;by&quot;, p.author, &quot;v&quot; + p.version)</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li>Plugins must implement the <code>UniDeskPluginInterface</code> abstract interface and override <code>registerQmlTypes</code> and <code>initialize</code>.</li><li>Plugin DLLs are placed in the <code>plugins/</code> subdirectory next to the application executable.</li><li>Failed plugins are skipped without interrupting the loading of other plugins.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./UniDeskPluginInterface">UniDeskPluginInterface</a> — C++ plugin interface</li><li><a href="./../../official-plugins">Official Plugins</a> — Official plugin pack</li><li><a href="/en/custom-developing/plugin">Plugin Development Guide</a> — Write your own plugins</li></ul>',23)]))}const g=i(s,[["render",l]]);export{h as __pageData,g as default};
